const input = $input.first().json;
const body = input.body || input;
const text = String(body.message || body.query || body.prompt || body.text || '').toLowerCase();
const wantsExecution = /plan|execute|draft|prepare|create|schedule|skill|task|meeting|mail|email|todo|kpi/.test(text);
const wantsKnowledge = /who|what|why|explain|context|knowledge|decision|source|evidence|graph/.test(text);
const route = wantsExecution ? 'agentic_butler' : 'answer_only';
return [{ json: {
  status: 'staging_ready',
  agent: 'Actor Twin',
  contract_version: '2026-08-06.2',
  role: 'Primary user-facing decision and answer interface for MeIDs.',
  route,
  decision: {
    intent: wantsExecution ? 'work_execution' : 'grounded_answer',
    use_knowledge_fabric: true,
    use_graph_context: wantsKnowledge,
    requires_human_approval: false,
    approval_reason: null
  },
  handoff: route === 'agentic_butler' ? { agent: 'Agentic Butler', webhook_path: '/webhook/meids/agentic-butler/run' } : null,
  retrieval_policy: { source_order: ['approved_okf', 'selected_pending_okf', 'vector_db_when_available', 'knowledge_graph'], cite_sources: true },
  received: body,
  next: 'Replace this contract node with LLM + OKF/vector/graph retrieval while preserving route and approval fields.'
} }];

